  let s = FULL_EXPOSURE;
  let knocked = false;
  let knockAtMs = -1;
  for (let t = 0; t <= 200; t++) {
    const r = tickExposure(s, 'radzone', DT, 1000 + t * 100);
    s = r.state;
    if (r.knocked && !knocked) {
      knocked = true;
      knockAtMs = 1000 + t * 100;
    }
  }
  expect(knocked).toBe(true);
  // 50 exposure / (5/s) = 10 s → the first tick at t = 10.0 s (ms 2000).
  expect(knockAtMs).toBe(2000);
  expect(s.exposure).toBe(0);
  expect(s.recoveringUntilMs).toBe(2000 + RECOVER_MS);
});

it('storm knock-down at exactly 25 s (50 / 2 per s)', () => {
  let s = FULL_EXPOSURE;
  let knockAtMs = -1;
  for (let t = 0; t <= 400; t++) {
    const r = tickExposure(s, 'storm', DT, 1000 + t * 100);
    s = r.state;
    if (r.knocked) {
      knockAtMs = 1000 + t * 100;
      break;
    }
  }
  expect(knockAtMs).toBe(1000 + 25_000);
});

it('no regen while recovering; knock fires exactly once; state exits recovering at the deadline', () => {
  let s = FULL_EXPOSURE;
  let knockCount = 0;
  for (let t = 0; t < 150; t++) {
    const r = tickExposure(s, 'radzone', DT, 1000 + t * 100);
    s = r.state;
    knockCount += r.knocked ? 1 : 0;
  }
  // Still recovering at t = 14 s (deadline 15 s).
  expect(s.recoveringUntilMs).toBe(2000 + RECOVER_MS);
  expect(s.exposure).toBe(0);
  expect(knockCount).toBe(1);
  // At the deadline the pool starts regening again (outside).
  const after = tickExposure(s, null, DT, 2000 + RECOVER_MS).state;
  expect(after.exposure).toBeCloseTo(EXPOSURE_REGEN_PER_S * DT, 9);
  expect(after.recoveringUntilMs).toBe(0);
});

