const GALAXY_SEED = 'HZ-SHARD-SEED';
function findPlanet(): { system: SystemGen; planet: Planet } {
  for (const starId of ['star-a', 'star-b', 'star-c', 'star-d', 'star-e']) {
    const sys = generateSystem(GALAXY_SEED, starId);
    for (const planet of sys.planets) {
      if (!planet.landable || planet.class === 'ocean' || planet.class === 'gas') continue;
      const solo: SystemGen = { ...sys, systemId: `${sys.systemId}-hz`, planets: [planet] };
      const hz = hazardsFor(GALAXY_SEED, solo);
      const kinds = new Set(hz.map((h) => h.kind));
      if (kinds.has('storm') && kinds.has('radzone') && kinds.has('drones')) return { system: solo, planet };
    }
  }
  throw new Error('no planet with all three hazard kinds found');
}
